class Solution {
  public int minimumIncompatibility(int[] nums, int k) {
    int n = nums.length, size = n / k, total = 1 << n;
    int[] sum = new int[total];
    boolean[] valid = new boolean[total];
    for (int mask = 1; mask < total; mask++) {
      int count = Integer.bitCount(mask);
      if (count != size) continue;
      boolean[] seen = new boolean[n + 1];
      int min = n + 1, max = 0;
      boolean ok = true;
      for (int i = 0; i < n; i++)
        if ((mask & (1 << i)) != 0) {
          if (seen[nums[i]]) {
            ok = false;
            break;
          }
          seen[nums[i]] = true;
          min = Math.min(min, nums[i]);
          max = Math.max(max, nums[i]);
        }
      if (ok) {
        valid[mask] = true;
        sum[mask] = max - min;
      }
    }
    int[] dp = new int[total];
    java.util.Arrays.fill(dp, 1_000_000);
    dp[0] = 0;
    for (int mask = 0; mask < total; mask++)
      if (dp[mask] < 1_000_000)
        for (int sub = (total - 1) ^ mask; sub > 0; sub = (sub - 1) & ((total - 1) ^ mask))
          if ((sub & -sub) == (((total - 1) ^ mask) & -((total - 1) ^ mask)) && valid[sub])
            dp[mask | sub] = Math.min(dp[mask | sub], dp[mask] + sum[sub]);
    return dp[total - 1] >= 1_000_000 ? -1 : dp[total - 1];
  }
}
